    /** The text for [key] in [language]. German is the fallback, then the key itself. */
    fun text(key: String, language: AppLanguage): String {
        val table = if (language == AppLanguage.ENGLISH) english else german
        return table[key] ?: german[key] ?: key
    }

    /** A text with its placeholders (%1$s, %1$d) filled in, as Android formats them. */
    fun format(key: String, language: AppLanguage, vararg args: Any): String =
        String.format(localeOf(language), text(key, language), *args)
}
